) AS aa(district_name, neighborhood_name, name, capacity, google_maps_url)
JOIN districts d ON d.name = aa.district_name
JOIN neighborhoods n ON n.name = aa.neighborhood_name AND n.district_id = d.id
-- Duplicate koruma: ayni mahalle + ayni ad zaten varsa insert etme
WHERE NOT EXISTS (
    SELECT 1 FROM assembly_areas ex
    WHERE ex.neighborhood_id = n.id
      AND LOWER(TRIM(ex.name)) = LOWER(TRIM(aa.name))
);
